export const postV1B2bIdpOauthAuthorizeStartRoute = createRoute({
  method: 'post',
  path: '/v1/b2b/idp/oauth/authorize/start',
  tags: ['B2B Idp'],
  summary: 'Authorizestart',
  description:
    "Initiates a request for authorization of a Connected App to access a Member's account.\n\nCall this endpoint using the query parameters from an OAuth Authorization request.\nThis endpoint validates various fields (`scope`, `client_id`, `redirect_uri`, `prompt`, etc...) are correct and returns\nrelevant information for rendering an OAuth Consent Screen.\n\nThis endpoint returns:\n- A public representation of the Connected App requesting authorization\n- Whether _explicit_ consent must be granted before proceeding with the authorization\n- A list of scopes the Member has the ability to grant the Connected App\n\nUse this response to prompt the Member for consent (if necessary) before calling the [Submit OAuth Authorization](https://stytch.com/docs/b2b/api/connected-apps-oauth-authorize) endpoint.\n\nExactly one of the following must be provided to identify the Member granting authorization:\n- `organization_id` + `member_id`\n- `session_token`\n- `session_jwt`\n\nIf a `session_token` or `session_jwt` is passed, the OAuth Authorization will be linked to the Member's session for tracking purposes.\nOne of these fields must be used if the Connected App intends to complete the [Exchange Access Token](https://stytch.com/docs/b2b/api/connected-app-access-token-exchange) flow.",
  operationId: 'api_b2b_idp_v1_b2b_idp_oauth_AuthorizeStart',
  request: {
    body: {
      content: {
        'application/json': { schema: ApiB2bIdpV1B2bIdpOauthAuthorizeStartRequestSchema },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': { schema: ApiB2bIdpV1B2bIdpOauthAuthorizeStartResponseSchema },
      },
    },
    400: { description: 'Bad request' },
    401: { description: 'Unauthorized', content: {} },
    429: { description: 'Too Many Requests', content: {} },
    500: { description: 'Internal server error', content: {} },
  },
})

export const postV1B2bIdpOauthAuthorizeRoute = createRoute({
  method: 'post',
  path: '/v1/b2b/idp/oauth/authorize',
  tags: ['B2B Idp'],
  summary: 'Authorize',
  description:
    "Completes a request for authorization of a Connected App to access a Member's account.\n\nCall this endpoint using the query parameters from an OAuth Authorization request, after previously validating those parameters using the\n[Preflight Check](https://stytch.com/docs/b2b/api/connected-apps-oauth-authorize-start) API.\nNote that this endpoint takes in a few additional parameters the preflight check does not- `state`, `nonce`, and `code_challenge`.\n\nIf the authorization was successful, the `redirect_uri` will contain a valid `authorization_code` embedded as a query parameter.\nIf the authorization was unsuccessful, the `redirect_uri` will contain an OAuth2.1 `error_code`.\nIn both cases, redirect the Member to the location for the response to be consumed by the Connected App.\n\nExactly one of the following must be provided to identify the Member granting authorization:\n- `organization_id` + `member_id`\n- `session_token`\n- `session_jwt`\n\nIf a `session_token` or `session_jwt` is passed, the OAuth Authorization will be linked to the Member's session for tracking purposes.\nOne of these fields must be used if the Connected App intends to complete the [Exchange Access Token](https://stytch.com/docs/b2b/api/connected-app-access-token-exchange) flow.",
  operationId: 'api_b2b_idp_v1_b2b_idp_oauth_Authorize',
  request: {
    body: {
      content: { 'application/json': { schema: ApiB2bIdpV1B2bIdpOauthAuthorizeRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response',
      content: { 'application/json': { schema: ApiB2bIdpV1B2bIdpOauthAuthorizeResponseSchema } },
    },
    400: { description: 'Bad request' },
    401: { description: 'Unauthorized', content: {} },
    429: { description: 'Too Many Requests', content: {} },
    500: { description: 'Internal server error', content: {} },
  },
})

