export const postV1SessionsAuthenticateRoute = createRoute({
  method: 'post',
  path: '/v1/sessions/authenticate',
  tags: ['Session'],
  summary: 'Authenticate',
  description:
    'Authenticate a session token or session JWT and retrieve associated session data. If `session_duration_minutes` is included, update the lifetime of the session to be that many minutes from now. All timestamps are formatted according to the RFC 3339 standard and are expressed in UTC, e.g. `2021-12-29T12:33:09Z`. This endpoint requires exactly one `session_jwt` or `session_token` as part of the request. If both are included, you will receive a `too_many_session_arguments` error.\n\nYou may provide a JWT that needs to be refreshed and is expired according to its `exp` claim. A new JWT will be returned if both the signature and the underlying Session are still valid. See our [How to use Stytch Session JWTs](https://stytch.com/docs/guides/sessions/using-jwts) guide for more information.',
  operationId: 'api_session_v1_Authenticate',
  request: {
    body: {
      content: { 'application/json': { schema: ApiSessionV1AuthenticateRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response',
      content: { 'application/json': { schema: ApiSessionV1AuthenticateResponseSchema } },
    },
    400: { description: 'Bad request' },
    401: { description: 'Unauthorized', content: {} },
    429: { description: 'Too Many Requests', content: {} },
    500: { description: 'Internal server error', content: {} },
  },
})

