export const postV1B2bSsoAuthenticateRoute = createRoute({
  method: 'post',
  path: '/v1/b2b/sso/authenticate',
  tags: ['Sso'],
  summary: 'Authenticate',
  description:
    "Authenticate a user given a token. \nThis endpoint verifies that the user completed the SSO Authentication flow by verifying that the token is valid and hasn't expired.\nProvide the `session_duration_minutes` parameter to set the lifetime of the session. \nIf the `session_duration_minutes` parameter is not specified, a Stytch session will be created with a 60 minute duration.\nTo link this authentication event to an existing Stytch session, include either the `session_token` or `session_jwt` param.\n\nIf the Member is required to complete MFA to log in to the Organization, the returned value of `member_authenticated` will be `false`, and an `intermediate_session_token` will be returned.\nThe `intermediate_session_token` can be passed into the [OTP SMS Authenticate endpoint](https://stytch.com/docs/b2b/api/authenticate-otp-sms), [TOTP Authenticate endpoint](https://stytch.com/docs/b2b/api/authenticate-totp),\nor [Recovery Codes Recover endpoint](https://stytch.com/docs/b2b/api/recovery-codes-recover) to complete the MFA step and acquire a full member session.\nThe `session_duration_minutes` and `session_custom_claims` parameters will be ignored.\n\nIf a valid `session_token` or `session_jwt` is passed in, the Member will not be required to complete an MFA step.",
  operationId: 'api_sso_v1_Authenticate',
  request: {
    body: {
      content: { 'application/json': { schema: ApiSsoV1AuthenticateRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response',
      content: { 'application/json': { schema: ApiSsoV1AuthenticateResponseSchema } },
    },
    400: { description: 'Bad request' },
    401: { description: 'Unauthorized', content: {} },
    429: { description: 'Too Many Requests', content: {} },
    500: { description: 'Internal server error', content: {} },
  },
})

